#include <esp_heap_caps.h>
#include <esp_timer.h>
#include <stdio.h>
#include <string.h>

#include "dl_image.hpp"
#include "human_face_detect.hpp"

// Generated at build time by build.sh from probe/human_face.jpg, so it cannot drift from the
// committed fixture the way a checked-in generated file would.
#include "facedet_image.h"

namespace {

HumanFaceDetect* g_det = nullptr;
char g_status[80] = "face:init";

void setStatus(const char* s)
{
    strncpy(g_status, s, sizeof(g_status) - 1);
    g_status[sizeof(g_status) - 1] = 0;
}

// The reference image ships with esp-dl's own human_face_detect example, so it is the input the
// model was demonstrated against -- which is what makes a miss meaningful rather than arguable.
constexpr int kExpectFaces = 1;
constexpr int kPasses = 8;

// §8.3 of the architecture note makes the keep-or-drop decision for esp-dl rest on ONE number that
// has never been measured: how much INTERNAL DRAM it takes. Internal DRAM is the binding resource
// (~250-310 KB against 32 MB of PSRAM) and the criterion is >= 64 KB free with a >= 32 KB largest
// block after the model is up. So measure it at the three points that decide it and put the answer
// where someone standing at the panel can read it, because that is the only channel that has
// reliably worked here.
size_t g_internalBefore = 0, g_internalAfterLoad = 0, g_internalAfterRuns = 0;

inline size_t internalFree()
{
    return heap_caps_get_free_size(MALLOC_CAP_INTERNAL);
}

}  // namespace

bool facedetBegin()
{
    if (g_det) return true;
    g_internalBefore = internalFree();
    g_det = new (std::nothrow) HumanFaceDetect();
    g_internalAfterLoad = internalFree();
    if (!g_det) {
        setStatus("face:MODEL LOAD FAILED");
        return false;
    }
    char b[80];
    snprintf(b, sizeof(b), "face:loaded int %uk->%uk", (unsigned)(g_internalBefore / 1024),
             (unsigned)(g_internalAfterLoad / 1024));
    setStatus(b);
    return true;
}

bool facedetAvailable()
{
    return g_det != nullptr;
}

void facedetSelfTest()
{
    if (!g_det) return;

    // Decode once, outside the timed loop: we are measuring INFERENCE, and folding a software JPEG
    // decode into that number would quietly make the model look several times slower than it is.
    auto img = dl::image::sw_decode_jpeg({(uint8_t*)kFaceProbeJpeg, sizeof(kFaceProbeJpeg)},
                                         dl::image::DL_IMAGE_PIX_TYPE_RGB888);
    if (!img.data) {
        // INCONCLUSIVE, not FAIL. The probe being broken is not the model being broken, and saying
        // so is the difference between a result and an accusation.
        setStatus("face:INCONCLUSIVE jpeg decode failed");
        return;
    }

    int64_t total = 0;
    size_t faces = 0;
    float bestScore = 0.0f;
    for (int i = 0; i < kPasses; ++i) {
        const int64_t t0 = esp_timer_get_time();
        auto& results = g_det->run(img);
        const int64_t dt = esp_timer_get_time() - t0;
        if (i == 0) {
            faces = results.size();
            for (const auto& r : results)
                if (r.score > bestScore) bestScore = r.score;
        } else {
            total += dt;
        }
    }
    g_internalAfterRuns = internalFree();
    const float steadyMs = (kPasses > 1) ? (float)total / (float)(kPasses - 1) / 1000.0f : 0.0f;

    char b[80];
    if (faces == kExpectFaces) {
        snprintf(b, sizeof(b), "face:PASS %.0fms s%.2f int %uk/%uk", steadyMs, bestScore,
                 (unsigned)(g_internalAfterRuns / 1024),
                 (unsigned)(heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL) / 1024));
    } else if (faces == 0) {
        snprintf(b, sizeof(b), "face:FAIL no face in ref image");
    } else {
        snprintf(b, sizeof(b), "face:FAIL %d faces, expected %d", (int)faces, kExpectFaces);
    }
    setStatus(b);

    heap_caps_free(img.data);
}

bool facedetRun(const uint8_t* rgb888, int w, int h, float* nx, float* ny, float* score)
{
    if (!g_det || !rgb888 || !nx || !ny || !score) return false;

    dl::image::img_t frame = {};
    frame.data = (void*)rgb888;
    frame.width = w;
    frame.height = h;
    frame.pix_type = dl::image::DL_IMAGE_PIX_TYPE_RGB888;

    auto& res = g_det->run(frame);
    if (res.empty()) return false;

    // LARGEST box, not highest score: the largest face is the nearest one, and the nearest person
    // is the one addressing the robot. Score is reported but does not choose -- it grades belief in
    // attention.cpp, which is a different question from which face to look at.
    const dl::detect::result_t* best = nullptr;
    int bestArea = -1;
    for (const auto& r : res) {
        const int a = (r.box[2] - r.box[0]) * (r.box[3] - r.box[1]);
        if (a > bestArea) {
            bestArea = a;
            best = &r;
        }
    }
    if (!best) return false;

    // SAME NORMALISATION AS motion.cpp, over the same buffer, with no extra flip. The live tracker
    // settled these signs by watching a reticle and recorded the result: the PPA stage already
    // applies mirror_x, so flipping again here makes two mirrors that cancel into backwards
    // tracking. Both cues therefore share one verified convention instead of each needing its own.
    const float cx = (float)(best->box[0] + best->box[2]) * 0.5f;
    const float cy = (float)(best->box[1] + best->box[3]) * 0.5f;
    float ox = cx / (float)w * 2.0f - 1.0f;
    float oy = cy / (float)h * 2.0f - 1.0f;
    if (ox < -1.0f) ox = -1.0f; else if (ox > 1.0f) ox = 1.0f;
    if (oy < -1.0f) oy = -1.0f; else if (oy > 1.0f) oy = 1.0f;
    *nx = ox;
    *ny = oy;
    *score = best->score;
    return true;
}

const char* facedetStatus()
{
    return g_status;
}

#endif  // OPENDUBS_FACEDET
